  BootstrapReservation: t.Object({
    reservationId: idSchema,
    status: bootstrapStatusSchema,
  }),
  BootstrapComplete: t.Object({
    principalId: t.Optional(idSchema),
    status: t.Literal("completed"),
    userId: t.Nullable(idSchema),
