import { Elysia } from "elysia";

import { type AuthEnvironment, type AuthInstance } from "../auth";
import { createAuthorizationPlugin } from "./authorization/plugin";
import { ApiModels } from "./models";

export function createDomainApiRoutes(
  environment: AuthEnvironment,
  auth: AuthInstance,
  name: string,
) {
  return new Elysia({ name: `shui-${name}-routes`, normalize: false })
    .use(createAuthorizationPlugin(environment, auth))
    .model(ApiModels);
}
import { Elysia, t } from "elysia";

import { PASSWORD_RESET_TIMING_FLOOR_MS, type AuthEnvironment, createAuth } from "./auth";
import { createApiRoutes } from "./modules";

function buildApiApp(environment: AuthEnvironment) {
  const auth = createAuth(environment);

  return new Elysia({ aot: false, prefix: "/api" })
    .onRequest(async ({ request }) => requireApiResource(request))
    .use(createApiRoutes(environment, auth))
    .get("/health", () => ({ service: "shui-api", status: "ok" as const }), {
      response: t.Object({
        service: t.String(),
        status: t.Literal("ok"),
      }),
    })
    .head("/health", () => new Response(null, { status: 204 }))
    .mount(async (request) => {
      const isPasswordReset =
        request.method === "POST" &&
        new URL(request.url).pathname.endsWith("/auth/request-password-reset");
      const startedAt = Date.now();
      const response = await auth.handler(request);
      if (isPasswordReset) {
        const remaining = PASSWORD_RESET_TIMING_FLOOR_MS - (Date.now() - startedAt);
        if (remaining > 0) await new Promise((resolve) => setTimeout(resolve, remaining));
      }
      return response;
    });
}

export type ApiApp = ReturnType<typeof buildApiApp>;

const apiAppCache = new WeakMap<AuthEnvironment, ApiApp>();

/** Reuse the fully typed Elysia route graph across requests in one isolate. */
export function createApiApp(environment: AuthEnvironment): ApiApp {
  const cached = apiAppCache.get(environment);
  if (cached) return cached;

  const app = buildApiApp(environment);
  apiAppCache.set(environment, app);
  return app;
}

async function requireApiResource(request: Request) {
  const url = new URL(request.url);
  const isAuthorize = url.pathname.endsWith("/oauth2/authorize");
  const isToken = url.pathname.endsWith("/oauth2/token");
  if (!isAuthorize && !isToken) return;

  if (isAuthorize) {
    const params = request.method === "GET" ? url.searchParams : await readOAuthBody(request);
    const scopes = params.get("scope")?.split(/\s+/) ?? [];
    if (scopes.includes("api:read") && !params.getAll("resource").some(Boolean)) {
      return invalidResourceResponse();
    }
    return;
  }

  const body = await readOAuthBody(request);
  if (body.get("grant_type") === "client_credentials" && !body.getAll("resource").some(Boolean)) {
    return invalidResourceResponse();
  }
}

async function readOAuthBody(request: Request) {
  const contentType = request.headers.get("content-type") ?? "";
  if (contentType.includes("application/x-www-form-urlencoded")) {
    return new URLSearchParams(await request.clone().text());
  }

  if (contentType.includes("application/json")) {
    const body = (await request
      .clone()
      .json()
      .catch(() => null)) as Record<string, unknown> | null;
    const params = new URLSearchParams();
    if (typeof body?.grant_type === "string") params.set("grant_type", body.grant_type);
    if (typeof body?.scope === "string") params.set("scope", body.scope);
    if (typeof body?.resource === "string") params.append("resource", body.resource);
    if (Array.isArray(body?.resource)) {
      for (const resource of body.resource) {
        if (typeof resource === "string") params.append("resource", resource);
      }
    }
    return params;
  }

  return new URLSearchParams();
}

function invalidResourceResponse() {
  return new Response(
    JSON.stringify({
      error: "invalid_target",
      error_description: "The api:read scope requires a resource indicator.",
    }),
    { headers: { "content-type": "application/json" }, status: 400 },
  );
}
import {
  type AuthEnvironment,
  type AuthInstance,
  isLocalEnvironment,
  readDevelopmentEmailSink,
} from "../../auth";
import { ApiError } from "../errors";
import { createDomainApiRoutes } from "../api-plugin";
import { completeBootstrap, completeSetup, getBootstrapStatus, reserveBootstrap } from "./service";

export function createBootstrapRoutes(environment: AuthEnvironment, auth: AuthInstance) {
  return createDomainApiRoutes(environment, auth, "bootstrap")
    .get(
      "/dev/email-sink",
      () => {
        if (!isLocalEnvironment(environment)) throw new ApiError(404);
        return { messages: [...readDevelopmentEmailSink()] };
      },
      { response: "EmailSink" },
    )
    .get("/bootstrap", () => getBootstrapStatus(environment), {
      response: "BootstrapStatus",
    })
    .get("/bootstrap/status", () => getBootstrapStatus(environment), {
      response: "BootstrapStatus",
    })
    .get("/setup", () => getBootstrapStatus(environment), {
      response: "BootstrapStatus",
    })
    .get("/setup/status", () => getBootstrapStatus(environment), {
      response: "BootstrapStatus",
    })
    .post("/bootstrap", ({ body, request }) => completeSetup(environment, auth, body, request), {
      body: "BootstrapCompleteBody",
      response: "BootstrapComplete",
    })
    .post("/setup", ({ body, request }) => completeSetup(environment, auth, body, request), {
      body: "BootstrapCompleteBody",
      response: "BootstrapComplete",
    })
    .post(
      "/bootstrap/reserve",
      ({ body, request }) => reserveBootstrap(environment, body, request),
      { body: "BootstrapTokenBody", response: "BootstrapReservation" },
    )
    .post("/setup/reserve", ({ body, request }) => reserveBootstrap(environment, body, request), {
      body: "BootstrapTokenBody",
      response: "BootstrapReservation",
    })
    .post(
      "/bootstrap/complete",
      ({ body, request }) => completeBootstrap(environment, auth, body, request),
      { body: "BootstrapCompleteBody", response: "BootstrapComplete" },
    )
    .post(
      "/setup/complete",
      ({ body, request }) => completeBootstrap(environment, auth, body, request),
      { body: "BootstrapCompleteBody", response: "BootstrapComplete" },
    );
}
import { type AuthEnvironment, type AuthInstance } from "../../auth";
import { createDomainApiRoutes } from "../api-plugin";
import { ApiError } from "../errors";
import {
  claimInvitationWithAuth,
  createInvitation,
  getPublicInvitation,
  revokeInvitation,
} from "./service";

export function createInvitationRoutes(environment: AuthEnvironment, auth: AuthInstance) {
  return createDomainApiRoutes(environment, auth, "invitations")
    .post(
      "/invitations",
      async ({ actor, body, request }) => {
        if (body.systemRoleKeys?.length && !actor.roleKeys.has("root")) {
          throw new ApiError(403);
        }
        return createInvitation(environment, actor, body, request);
      },
      {
        body: "InvitationCreateBody",
        requirePermission: "users:write",
        response: "InvitationCreated",
      },
    )
    .get(
      "/invitations/:token",
      ({ params, request }) => getPublicInvitation(environment, params.token, request),
      { params: "TokenParams", response: "InvitationPublic" },
    )
    .post(
      "/invitations/:token/accept",
      ({ body, params, request }) =>
        claimInvitationWithAuth(environment, auth, params.token, body, request),
      {
        body: "InvitationAcceptBody",
        params: "TokenParams",
        response: "InvitationAccepted",
      },
    )
    .post(
      "/invitations/:token/claim",
      ({ body, params, request }) =>
        claimInvitationWithAuth(environment, auth, params.token, body, request),
      {
        body: "InvitationAcceptBody",
        params: "TokenParams",
        response: "InvitationAccepted",
      },
    )
    .post(
      "/invitations/:token/complete",
      ({ body, params, request }) =>
        claimInvitationWithAuth(environment, auth, params.token, body, request),
      {
        body: "InvitationAcceptBody",
        params: "TokenParams",
        response: "InvitationAccepted",
      },
    )
    .post(
      "/invitations/:token/revoke",
      async ({ actor, params, request }) =>
        revokeInvitation(environment, actor, params.token, request),
      {
        params: "TokenParams",
        requirePermission: "users:write",
        response: "InvitationRevoked",
      },
    );
}

